use caveat_runtime::{ast::Statement,eval::{self,EventKind},parser,Attention,NodeKind,Relation};
fn run_with(inv:&str,action:&str)->eval::Evaluation{let mut p=parser::parse(include_str!("../../game/the_door_round2.cav")).unwrap();for s in&mut p.statements{match s{Statement::Inspect{investigation,caveat,..}if investigation=="predoor"=>*caveat=inv.into(),Statement::Select{choice,option}if choice=="door_decision"=>*option=action.into(),_=>{}}}eval::evaluate(&p).unwrap()}
fn snap<'a>(e:&'a eval::Evaluation,a:&str)->&'a eval::EpistemicSnapshot{let id=e.symbols[a];e.history.iter().find_map(|x|match &x.kind{EventKind::Committed{commitment,snapshot,..}if *commitment==id=>Some(snapshot),_=>None}).unwrap()}
fn att(e:&eval::Evaluation,a:&str,c:&str)->Attention{match snap(e,a).nodes.get(&e.symbols[c]).unwrap(){NodeKind::Caveat{attention,..}=>*attention,_=>panic!()}}
#[test]fn latch_reveals_maintenance_not_camera_diagnostic(){let e=run_with("latch_sensor_recently_serviced","open");assert_eq!(att(&e,"open","latch_sensor_recently_serviced"),Attention::Examined);assert_eq!(att(&e,"open","camera_has_blind_spot"),Attention::Unexamined);let s=snap(&e,"open");let m=e.symbols["maintenance_record"];let d=e.symbols["coverage_test"];assert!(s.edges.iter().any(|x|x.from==m&&x.relation==Relation::Opposes));assert!(!s.edges.iter().any(|x|x.from==d&&x.relation==Relation::Opposes));}
#[test]fn camera_reveals_diagnostic_not_maintenance(){let e=run_with("camera_has_blind_spot","wait");assert_eq!(att(&e,"wait","camera_has_blind_spot"),Attention::Examined);assert_eq!(att(&e,"wait","latch_sensor_recently_serviced"),Attention::Unexamined);let s=snap(&e,"wait");let m=e.symbols["maintenance_record"];let d=e.symbols["coverage_test"];assert!(s.edges.iter().any(|x|x.from==d&&x.relation==Relation::Opposes));assert!(!s.edges.iter().any(|x|x.from==m&&x.relation==Relation::Opposes));}
